/**
 * Instantiate scenario with deep clone, assign killer and inject subtle clues
 */
function instantiateScenario(scenarioData, killerSuspectId) {
  const suspect = getSuspectById(killerSuspectId);

  // Clone deeply
  const scenarioInstance = JSON.parse(JSON.stringify(scenarioData));
  scenarioInstance.killerSuspectId = killerSuspectId;
  scenarioInstance.killerName = suspect?.name || 'คนร้าย';

  // Available room keys excluding Grand Hall for distributing subtle clues
  const roomKeys = [
    'kitchen', 'ballroom', 'conservatory',
    'dining-room', 'billiard-room', 'study',
    'library', 'lounge'
  ];
  // Shuffle room keys
  const shuffledRooms = [...roomKeys].sort(() => Math.random() - 0.5);

  // Exactly 5 subtle clues defined specifically for this scenario pattern
  const subtleClues = (scenarioInstance.subtleKillerClues || []).slice(0, 5);
  
  // Coordinate presets for room markers so they look well-placed
  const markerCoords = [
    { x: 35, y: 38 },
    { x: 68, y: 72 },
    { x: 42, y: 78 },
    { x: 75, y: 45 },
    { x: 28, y: 62 }
  ];

  subtleClues.forEach((sc, i) => {
    const assignedRoom = shuffledRooms[i];
    const coords = markerCoords[i];
    scenarioInstance.specialClues.push({
      id: `clue_killer_${killerSuspectId}_${scenarioData.id}_${i + 1}`,
      roomId: assignedRoom,
      x: coords.x,
      y: coords.y,
 title: sc.title,
      isCritical: true,
      isKillerClue: true,
      canBeWiped: true,
 revealTitle: sc.revealTitle,
 revealDesc: sc.revealDesc,
 wipedText: sc.wipedText
    });
  });

  return scenarioInstance;
}

// ============================================================
//  54-SCENARIO NON-REPEATING SHUFFLED CYCLE MANAGER
//  - 54 matches in a row are guaranteed to play all 54 distinct scenarios without repetition.
//  - Every 6 consecutive games feature 6 distinct killer characters (zero duplicate killers in each 6-game set).
//  - Each new cycle reshuffles the entire deck of 54 scenarios into a brand new random order.
// ============================================================
const SCENARIO_CYCLE_DECK_KEY = 'cluedo_scenario_cycle_deck';
const SCENARIO_CYCLE_INDEX_KEY = 'cluedo_scenario_cycle_index';

let inMemoryScenarioDeck = null;
let inMemoryScenarioIndex = 0;

function shuffleArray(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function getScenarioCycleState() {
  try {
    if (typeof localStorage !== 'undefined') {
      const storedDeck = localStorage.getItem(SCENARIO_CYCLE_DECK_KEY);
      const storedIdx = localStorage.getItem(SCENARIO_CYCLE_INDEX_KEY);
      if (storedDeck && storedIdx !== null) {
        const deck = JSON.parse(storedDeck);
        const idx = parseInt(storedIdx, 10);
        if (Array.isArray(deck) && deck.length === SCENARIOS.length && !isNaN(idx)) {
          return { deck, index: idx };
        }
      }
    }
  } catch (e) {}

  if (inMemoryScenarioDeck && inMemoryScenarioDeck.length === SCENARIOS.length) {
    return { deck: inMemoryScenarioDeck, index: inMemoryScenarioIndex };
  }

  // Generate new shuffled deck
  return createNewShuffledCycleDeck();
}

function saveScenarioCycleState(deck, index) {
  inMemoryScenarioDeck = deck;
  inMemoryScenarioIndex = index;
  try {
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(SCENARIO_CYCLE_DECK_KEY, JSON.stringify(deck));
      localStorage.setItem(SCENARIO_CYCLE_INDEX_KEY, String(index));
    }
  } catch (e) {}
}

function createNewShuffledCycleDeck(previousDeck = null) {
  // Guarantee that in every 6-game window, all 6 suspects are the killer once (zero duplicate killers in each 6-game set)
  // 54 scenarios total = 9 sets of 6 games
  const sets = Array.from({ length: 9 }, () => []);

  SUSPECTS.forEach(suspect => {
    const suspectScenarios = shuffleArray(SCENARIOS.filter(s => s.applicableKiller === suspect.id));
    for (let i = 0; i < 9; i++) {
      if (suspectScenarios[i]) {
        sets[i].push(suspectScenarios[i].id);
      }
    }
  });

  // Shuffle each 6-game set independently and concatenate into 54-game deck
  let newDeck = [];
  sets.forEach(s => {
    newDeck.push(...shuffleArray(s));
  });

  // If there was a previous deck, ensure the new cycle is not in the exact same order
  if (previousDeck && previousDeck.length === 54 && JSON.stringify(newDeck) === JSON.stringify(previousDeck)) {
    newDeck = [];
    sets.forEach(s => {
      newDeck.push(...shuffleArray(s));
    });
  }

  saveScenarioCycleState(newDeck, 0);
  return { deck: newDeck, index: 0 };
}

function resetScenarioCycle() {
  const currentState = getScenarioCycleState();
  return createNewShuffledCycleDeck(currentState ? currentState.deck : null);
}

/**
 * Get the next unplayed scenario in the 54-scenario shuffled cycle.
 * Guarantees zero duplicate cases across 54 consecutive games, and reshuffles randomly every cycle.
 */
function getNextUnplayedScenario() {
  let { deck, index } = getScenarioCycleState();

  // If current deck has been completely played (54 games finished), reshuffle for a new 54-game cycle
  if (index >= deck.length) {
    const newCycle = createNewShuffledCycleDeck(deck);
    deck = newCycle.deck;
    index = newCycle.index;
  }

  const scenarioId = deck[index];
  const nextIndex = index + 1;
  saveScenarioCycleState(deck, nextIndex);

  const scenarioData = SCENARIOS.find(s => s.id === scenarioId) || SCENARIOS[0];
  const scenarioInstance = instantiateScenario(scenarioData, scenarioData.applicableKiller);

  // Attach cycle progress info
  scenarioInstance.cycleRound = nextIndex;
  scenarioInstance.cycleTotal = deck.length; // 54

  return scenarioInstance;
}

/**
 * Direct killer scenario lookup helper
 */
function selectScenarioForKiller(killerSuspectId) {
  const matching = SCENARIOS.filter(s => s.applicableKiller === killerSuspectId);
  const candidates = matching.length > 0 ? matching : SCENARIOS;
  const chosen = candidates[Math.floor(Math.random() * candidates.length)];
  return instantiateScenario(chosen, killerSuspectId);
}

/**
 * Compile all clue markers for a specific room given the active scenario
 * Guarantees at least 3 clues per room across all 9 rooms
 */
function getCluesForRoom(roomId, activeScenario) {
  const clues = [];

  // 1. Add scenario special clues that belong to this room
  if (activeScenario && activeScenario.specialClues) {
    activeScenario.specialClues.forEach(c => {
      if (c.roomId === roomId) {
        clues.push({
          ...c,
          isKillerEvidence: true,
          wiped: false,
          inspected: false,
          inspectedBy: []
        });
      }
    });
  }

  // 2. Add default decoy clues
  const defaults = DEFAULT_ROOM_CLUES[roomId] || [];
  defaults.forEach(d => {
    // Avoid duplicate IDs if already present
    if (!clues.some(existing => existing.id === d.id)) {
      clues.push({
        ...d,
        roomId: roomId,
        isKillerEvidence: false,
        canBeWiped: false,
        wiped: false,
        inspected: false,
        inspectedBy: []
      });
    }
  });

  return clues;
}




